CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS public.profiles (id uuid PRIMARY KEY, username text, email text, full_name text, role text DEFAULT 'student', created_at timestamptz DEFAULT now());
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS username text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS email text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name text; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role text DEFAULT 'student'; ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now();
CREATE TABLE IF NOT EXISTS public.learning_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, strengths jsonb NOT NULL DEFAULT '{}'::jsonb, weaknesses jsonb NOT NULL DEFAULT '{}'::jsonb, preferred_style text, difficulty_level text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.student_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, topic text, progress integer, mastery_level text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, title text NOT NULL DEFAULT 'New conversation', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user','assistant','system')), content text NOT NULL, meta jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.learning_profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.student_progress ENABLE ROW LEVEL SECURITY; ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS profiles_is_owner ON public.profiles; CREATE POLICY profiles_is_owner ON public.profiles FOR SELECT USING (auth.uid() = id);
DROP POLICY IF EXISTS profiles_insert_own ON public.profiles; CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);
DROP POLICY IF EXISTS profiles_update_own ON public.profiles; CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
DROP POLICY IF EXISTS learning_profiles_is_owner ON public.learning_profiles; CREATE POLICY learning_profiles_is_owner ON public.learning_profiles FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS student_progress_is_owner ON public.student_progress; CREATE POLICY student_progress_is_owner ON public.student_progress FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS conversations_is_owner ON public.conversations; CREATE POLICY conversations_is_owner ON public.conversations FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS messages_is_owner ON public.messages; CREATE POLICY messages_is_owner ON public.messages FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE OR REPLACE FUNCTION public.create_auth_profile() RETURNS trigger AS $$ BEGIN INSERT INTO public.profiles (id,email,username,full_name,role,created_at) VALUES (NEW.id,NEW.email,COALESCE(NEW.raw_user_meta_data ->> 'username',split_part(NEW.email,'@','1')),NEW.raw_user_meta_data ->> 'full_name','student',now()) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER;
DROP TRIGGER IF EXISTS auth_user_profile_insert ON auth.users; CREATE TRIGGER auth_user_profile_insert AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_auth_profile();
